package net.civeira.phylax.feature.observe.observedprobe.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.valueobject.ExpectedStatusVO;

@RequiredArgsConstructor
public class ExpectedStatusValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<ExpectedStatusVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param expectedStatus
   * @return
   */
  public T expectedStatus(ExpectedStatusVO expectedStatus) {
    this.value = Optional.of(expectedStatus);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param expectedStatus
   * @return
   */
  public T expectedStatus(Optional<ExpectedStatusVO> expectedStatus) {
    this.value = expectedStatus;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param expectedStatus
   * @return
   */
  public T expectedStatus(Integer expectedStatus) {
    this.value = Optional.of(ExpectedStatusVO.from(expectedStatus));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<Integer> getExpectedStatus() {
    return value.map(ExpectedStatusVO::getExpectedStatus);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<ExpectedStatusVO> getExpectedStatusValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public ExpectedStatusVO readExpectedStatus(final Optional<ObservedProbe> original,
      final ConstraintFailList fails) {
    ExpectedStatusVO result =
        value.orElse(original.map(ObservedProbe::getExpectedStatusValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "expectedStatus", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetExpectedStatus() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetExpectedStatusIfMatches(final String field) {
    if ("expectedStatus".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
